/**
 * Math records (Phase 3) — the single validated content source for math.
 *
 * Generated by /tmp/gen-math-records.mts from
 * docs/scaling/math/number/items.json, docs/scaling/math/applied/items.json
 * and src/subjects/math/answers.ts (pre-move). Content bytes come from those
 * inputs only: do not hand-edit a record here, and do not retype one.
 * The next math PR deletes the answers.ts compatibility export.
 *
 * Each record is one SubjectItem: the UnitItem fields (contract I2) plus its
 * answer, provenance, media rules and lead policy. Screens read projections
 * of these records (mathUnits, answerFor); they never join files by hand.
 * Provenance is UNVERIFIED for all 53 records: no verifiedOn date exists
 * for these rows. Media is empty for all 53: math carries no clip or still
 * ids today. Lead policy is answer-not-in-lead for every record.
 *
 * Deal order: WAVE1_ITEM_IDS below — wave 1 first (up to 3 items per band),
 * then the wave-2 additions appended per band, then the wave-3 additions
 * appended per band, so the dealt first case per band is unchanged.
 */
import { z } from "zod";
import numberRows from "../../../docs/scaling/math/number/items.json" with { type: "json" };
import appliedRows from "../../../docs/scaling/math/applied/items.json" with { type: "json" };

const GroupSchema = z.enum(["7-10", "10-18", "18+"]);

const StandardSchema = z.union([
  z.object({ code: z.string(), source: z.string() }),
  z.literal("UNVERIFIED"),
]);

const ProvenanceSchema = z.union([
  z.literal("UNVERIFIED"),
  z.object({ source: z.string(), verifiedOn: z.string().regex(/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/) }),
]);

const MediaSchema = z.array(
  z.object({
    id: z.string().min(1),
    kind: z.enum(["clip", "still"]),
    revealsAnswer: z.boolean(),
  }),
);

const answerFields = {
  prompt: z.string().min(1),
  choices: z.array(z.string()),
  correct: z.string().min(1),
  derivation: z.string().min(1),
  value: z.number().optional(),
  kind: z.enum(["choice", "number"]).optional(),
};

/**
 * Answer shape (local mirror of src/subjects/shared/answer.ts: AnswerEntry
 * — importing it from this Content file would be an upward import).
 * kind discriminates: "number" asks the player to type a number (value
 * required, choices may be empty); anything else picks from choices.
 * followUp is one level only: a follow-up has no follow-up of its own.
 */
function refineAnswer(
  answer: { kind?: "choice" | "number"; value?: number; choices: string[]; correct: string },
  ctx: z.RefinementCtx,
): void {
  if (answer.kind === "number") {
    if (answer.value === undefined) {
      ctx.addIssue({ code: "custom", message: "number answer requires value" });
    }
  } else {
    if (answer.choices.length === 0) {
      ctx.addIssue({ code: "custom", message: "choice answer requires choices" });
    }
    if (!answer.choices.includes(answer.correct)) {
      ctx.addIssue({ code: "custom", message: "correct must be one of choices" });
    }
  }
}

const AnswerBaseSchema = z.object(answerFields).superRefine(refineAnswer);

export const AnswerSchema = z
  .object({ ...answerFields, followUp: z.lazy(() => AnswerBaseSchema).optional() })
  .superRefine(refineAnswer);

/** The one validated record shape for a subject item (contract I2 + Phase 3). */
export const SubjectItemSchema = z.object({
  id: z.string().min(1),
  group: GroupSchema,
  objective: z.string().min(1),
  standard: StandardSchema,
  why: z.string().min(1),
  buildsOn: z.array(z.string()),
  useElsewhere: z.array(z.string()),
  answer: AnswerSchema,
  provenance: ProvenanceSchema,
  media: MediaSchema,
  leadPolicy: z.literal("answer-not-in-lead"),
});

export type SubjectItem = z.infer<typeof SubjectItemSchema>;
export type SubjectAnswer = z.infer<typeof AnswerSchema>;
export type UnitItem = Omit<SubjectItem, "answer" | "provenance" | "media" | "leadPolicy">;
export type AgeGroup = SubjectItem["group"];

